@push('head')<style>.theme-preview{margin-top:18px;border:1px solid var(--admin-border);border-radius:12px;overflow:hidden}.preview-head{display:flex;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid var(--admin-border);font-size:11px;font-weight:700}.preview-head small{font-size:9px;color:var(--admin-muted);font-weight:400}.preview-surface{padding:24px;background:#020a10}.preview-card{max-width:520px;padding:var(--pv-card-padding,24px);border:1px solid var(--pv-border-soft,rgba(96,216,239,.16));border-radius:var(--pv-radius,12px);background:var(--pv-surface,#07131a);color:var(--pv-text,#eaf7fb)}.preview-status{display:inline-flex;margin:12px 0 0 8px;padding:4px 8px;border:1px solid var(--pv-success,#5fd39b);border-radius:999px;color:var(--pv-success,#5fd39b);font-size:10px;font-weight:700}.preview-card h3{margin:0 0 10px;font-size:22px;font-family:var(--pv-heading,Inter,sans-serif)}.preview-card p{margin:0 0 18px;color:var(--pv-muted,#8ea8b2);font:var(--pv-base,16px)/var(--pv-line,1.6) var(--pv-body,Inter,sans-serif)}#preview-button{height:var(--pv-button-height,42px);padding:0 16px;border:0;border-radius:var(--pv-button-radius,10px);background:var(--pv-primary,#55cce7);color:#041017;font-weight:700;cursor:pointer}#preview-input{display:block;width:100%;box-sizing:border-box;height:var(--pv-button-height,42px);margin-top:12px;padding:0 12px;border:1px solid var(--pv-border-soft,rgba(96,216,239,.22));border-radius:var(--pv-input-radius,10px);background:transparent;color:inherit}.theme-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.color-row{display:flex;gap:8px}.color-row input[type=color]{width:42px;height:38px;padding:3px;border:1px solid var(--admin-border);border-radius:9px;background:transparent}@media(max-width:800px){.theme-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.theme-grid{grid-template-columns:1fr}}</style><script>
(function(){const q=s=>document.querySelector(s), f=document.querySelector('form'), root=q('.preview-card'); if(!f||!root)return;
const map={'theme.primary':'--pv-primary','theme.success':'--pv-success','theme.warning':'--pv-warning','theme.danger':'--pv-danger','theme.border_soft':'--pv-border-soft','theme.icon':'--pv-icon','theme.overlay':'--pv-overlay','theme.shadow':'--pv-shadow','theme.surface':'--pv-surface','theme.text':'--pv-text','theme.muted':'--pv-muted','theme.radius':'--pv-radius','theme.font_body':'--pv-body','theme.font_heading':'--pv-heading','theme.base_size':'--pv-base','theme.line_height':'--pv-line','theme.card_padding':'--pv-card-padding','theme.button_radius':'--pv-button-radius','theme.button_height':'--pv-button-height','theme.input_radius':'--pv-input-radius'};
function sync(){Object.entries(map).forEach(([name,token])=>{const el=f.querySelector('[name="'+name+'"]');if(el)root.style.setProperty(token,(el.type==='color'?el.value:el.value+( /radius|padding|height|base/.test(name)?'px':'')));});}
f.querySelectorAll('input').forEach(el=>el.addEventListener('input',sync)); sync();})();
</script>@endpush
